import { useState, useEffect, useCallback } from 'react'
import { useNavigate } from 'react-router-dom'
import { useAuth } from '../context/AuthContext'
import { useToast } from '../context/ToastContext'
import {
  BonusEntryForm,
  WebsiteLinksForm,
  GiveawayEditor,
  LocationEditor,
} from '../components/Admin/AdminForms'
import { SideNavbar, FooterAdmin, AdminHeader } from '../components/Admin/AdminLayout'

function AdminDashboard() {
  const { user, token, logout } = useAuth()
  const { showToast } = useToast()
  const navigate = useNavigate()

  const navItems = [
    { id: 'dashboard', label: 'Members', icon: 'group' },
    { id: 'bonus-entry', label: 'Points Hub', icon: 'account_balance_wallet' },
    { id: 'giveaways', label: 'Reward Hub', icon: 'featured_seasonal' },
    { id: 'locations', label: 'Storefronts', icon: 'storefront' },
    { id: 'links', label: 'Connect', icon: 'share' },
  ]

  const [activeTab, setActiveTab] = useState('dashboard') // dashboard, bonus-entry, giveaways, locations, links
  const [viewMode, setViewMode] = useState('list') // list, add-user, user-details
  const [selectedUser, setSelectedUser] = useState(null)
  const [showDeleteModal, setShowDeleteModal] = useState(false)
  const [deleteConfirmText, setDeleteConfirmText] = useState('')
  const [detailTab, setDetailTab] = useState('details') // details, points for user details view

  // Giveaway State
  const [giveaways, setGiveaways] = useState([])
  const [giveawayMode, setGiveawayMode] = useState('grid')
  const [editingGiveaway, setEditingGiveaway] = useState(null)

  // Locations State
  const [locations, setLocations] = useState([])
  const [locationMode, setLocationMode] = useState('grid')
  const [editingLocation, setEditingLocation] = useState(null)

  const [users, setUsers] = useState([])
  const [searchQuery, setSearchQuery] = useState('')
  const [loading, setLoading] = useState(false)

  const filteredUsers = users.filter((u) => {
    const fullName = `${u.first_name || ''} ${u.last_name || ''}`.toLowerCase()
    const email = (u.email || '').toLowerCase()
    const query = searchQuery.toLowerCase()
    return fullName.includes(query) || email.includes(query)
  })

  const [quickPoints, setQuickPoints] = useState('')
  const [manualPointsAmount, setManualPointsAmount] = useState('')
  const [addUserForm, setAddUserForm] = useState({ full_name: '', email: '', points: '' })
  const [editUserForm, setEditUserForm] = useState({ first_name: '', last_name: '', email: '' })

  const fetchUsers = useCallback(async () => {
    try {
      const res = await fetch('/api/users_list', {
        headers: { Authorization: `Bearer ${token}` },
      })
      const data = await res.json()
      setUsers(Array.isArray(data) ? data : [])
    } catch (err) {
      console.error('Failed to fetch users', err)
      setUsers([])
    }
  }, [token])

  const fetchGiveaways = useCallback(async () => {
    try {
      const res = await fetch('/api/giveaways', {
        headers: { Authorization: `Bearer ${token}` },
      })
      const data = await res.json()
      setGiveaways(Array.isArray(data) ? data : [])
    } catch (err) {
      console.error('Failed to fetch giveaways', err)
      setGiveaways([])
    }
  }, [token])

  const fetchLocations = useCallback(async () => {
    try {
      const res = await fetch('/api/locations', {
        headers: { Authorization: `Bearer ${token}` },
      })
      const data = await res.json()
      setLocations(Array.isArray(data) ? data : [])
    } catch (err) {
      console.error('Failed to fetch locations', err)
      setLocations([])
    }
  }, [token])

  useEffect(() => {
    fetchUsers()
    fetchGiveaways()
    fetchLocations()
  }, [fetchUsers, fetchGiveaways, fetchLocations])

  useEffect(() => {
    if (selectedUser) {
      setEditUserForm({
        first_name: selectedUser.first_name || '',
        last_name: selectedUser.last_name || '',
        email: selectedUser.email || '',
      })
    }
  }, [selectedUser])

  const handleQuickPoints = async (email, points) => {
    if (!email || !points) return
    setLoading(true)
    try {
      const res = await fetch('/api/transactions/quick_add', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
        body: JSON.stringify({ email: email, points: points }),
      })
      if (res.ok) {
        fetchUsers()
        showToast('Points added successfully!')
      }
    } catch (err) {
      console.error(err)
    } finally {
      setLoading(false)
    }
  }

  const handleManualAddPoints = async () => {
    if (!selectedUser || !manualPointsAmount) return
    setLoading(true)
    try {
      const res = await fetch(`/api/users/${selectedUser.id}/add_points`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
        body: JSON.stringify({ points: manualPointsAmount, notes: 'Admin Manual Addition' }),
      })
      if (res.ok) {
        const data = await res.json()
        setSelectedUser({ ...selectedUser, points_balance: data.new_balance })
        setManualPointsAmount('')
        fetchUsers()
      } else {
        const errData = await res.json()
        showToast(
          `Failed to add points: ${errData.error || errData.errors || 'Access denied'}`,
          'error'
        )
      }
    } catch (err) {
      console.error(err)
      showToast('Network error occurred while adding points.', 'error')
    } finally {
      setLoading(false)
    }
  }

  const handleDeleteUser = async () => {
    if (!selectedUser) return
    setLoading(true)
    try {
      const res = await fetch(`/api/users/${selectedUser.id}`, {
        method: 'DELETE',
        headers: { Authorization: `Bearer ${token}` },
      })
      if (res.ok) {
        setShowDeleteModal(false)
        setDeleteConfirmText('')
        setViewMode('list')
        fetchUsers()
      }
    } catch (err) {
      console.error(err)
    } finally {
      setLoading(false)
    }
  }

  const handleCreateUser = async () => {
    if (!addUserForm.email || !addUserForm.full_name) {
      showToast('Name and Email are required', 'error')
      return
    }
    setLoading(true)
    try {
      const res = await fetch('/api/register', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          email: addUserForm.email,
          first_name: addUserForm.full_name.trim().split(' ')[0] || addUserForm.full_name.trim(),
          last_name: addUserForm.full_name.trim().split(' ').slice(1).join(' ') || '',
          password: 'Password123!',
          role: 'customer',
        }),
      })

      if (res.ok) {
        const userData = await res.json()
        if (addUserForm.points && Number(addUserForm.points) !== 0 && userData.id) {
          try {
            await fetch(`/api/users/${userData.id}/add_points`, {
              method: 'POST',
              headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
              body: JSON.stringify({
                points: addUserForm.points,
                notes: 'Initial Sign-up Bonus',
              }),
            })
          } catch (pointErr) {
            console.error('Failed to add initial points:', pointErr)
          }
        }
        showToast(`Invitation sent to ${addUserForm.email}!`, 'success')
        setAddUserForm({ full_name: '', email: '', points: '' })
        setViewMode('list')
        fetchUsers()
      } else {
        const errorData = await res.json()
        showToast(
          errorData.error || errorData.errors?.join(', ') || 'Failed to create user',
          'error'
        )
      }
    } catch (err) {
      console.error(err)
      showToast('Network error', 'error')
    } finally {
      setLoading(false)
    }
  }

  const handleSaveGiveaway = async (giveawayData) => {
    setLoading(true)
    try {
      const url = giveawayData.id ? `/api/giveaways/${giveawayData.id}` : '/api/giveaways'
      const method = giveawayData.id ? 'PUT' : 'POST'
      await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
        body: JSON.stringify({ giveaway: giveawayData }),
      })
      fetchGiveaways()
      setGiveawayMode('grid')
    } catch (err) {
      console.error(err)
    } finally {
      setLoading(false)
    }
  }

  const handleSaveLocation = async (locationData) => {
    setLoading(true)
    try {
      const url = locationData.id ? `/api/locations/${locationData.id}` : '/api/locations'
      const method = locationData.id ? 'PUT' : 'POST'
      await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
        body: JSON.stringify({ location: locationData }),
      })
      fetchLocations()
      setLocationMode('grid')
    } catch (err) {
      console.error(err)
    } finally {
      setLoading(false)
    }
  }

  const handleDeleteGiveaway = async (id) => {
    setLoading(true)
    try {
      await fetch(`/api/giveaways/${id}`, {
        method: 'DELETE',
        headers: { Authorization: `Bearer ${token}` },
      })
      fetchGiveaways()
      setGiveawayMode('grid')
    } catch (err) {
      console.error(err)
    } finally {
      setLoading(false)
    }
  }

  const handleDeleteLocation = async (id) => {
    setLoading(true)
    try {
      await fetch(`/api/locations/${id}`, {
        method: 'DELETE',
        headers: { Authorization: `Bearer ${token}` },
      })
      fetchLocations()
      setLocationMode('grid')
    } catch (err) {
      console.error(err)
    } finally {
      setLoading(false)
    }
  }

  const getStatusBadge = (points) => {
    if (points >= 1500) return { label: 'PLATINUM', class: 'bg-[#4A6B10] text-white' }
    if (points >= 1000) return { label: 'GOLD', class: 'bg-[#BFE9A2] text-[#304c00]' }
    if (points >= 500) return { label: 'SILVER', class: 'bg-[#E2EAD3] text-[#4A5440]' }
    return { label: 'BRONZE', class: 'bg-[#D1D3C8] text-white' }
  }

  const renderDeleteModal = () => (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/50 backdrop-blur-md animate-fade-in px-6">
      <div className="bg-[#FBFBF5] rounded-[3rem] p-10 md:p-14 max-w-lg w-full shadow-2xl border border-white/20 relative animate-scale-in">
        <div className="flex flex-col items-center mb-10">
          <div className="w-16 h-16 rounded-full bg-red-50 flex items-center justify-center mb-6">
            <span className="material-symbols-outlined text-red-500 text-3xl">warning</span>
          </div>
          <h3 className="text-[#1a2a00] text-3xl font-bold font-headline text-center mb-3">
            Confirm Deletion
          </h3>
          <p className="text-on-surface-variant/70 text-center font-medium leading-relaxed max-w-[280px]">
            You are about to permanently remove{' '}
            <span className="text-red-600 font-bold">
              {selectedUser?.first_name} {selectedUser?.last_name}
            </span>
            . This cannot be undone.
          </p>
        </div>
        <div className="space-y-8">
          <div className="space-y-3">
            <label className="block text-[10px] font-black text-on-surface-variant/40 uppercase tracking-[0.2em] text-center">
              Type 'DELETE' to confirm
            </label>
            <input
              type="text"
              value={deleteConfirmText}
              onChange={(e) => setDeleteConfirmText(e.target.value)}
              placeholder="Type here..."
              className="w-full bg-[#EEF4E4] border-none rounded-2xl px-6 py-4 text-center font-bold text-red-600 outline-none shadow-inner"
            />
          </div>
          <div className="flex gap-4">
            <button
              onClick={handleDeleteUser}
              disabled={deleteConfirmText !== 'DELETE' || loading}
              className="flex-1 bg-red-600 text-white font-bold py-4 rounded-full shadow-lg shadow-red-200 hover:bg-red-700 transition-all active:scale-95 disabled:opacity-20"
            >
              Confirm Delete
            </button>
            <button
              onClick={() => {
                setShowDeleteModal(false)
                setDeleteConfirmText('')
              }}
              className="flex-1 bg-white border-2 border-[#D1D3C8] text-on-surface-variant font-bold py-4 rounded-full hover:bg-surface-container-highest/20 transition-all active:scale-95"
            >
              Cancel
            </button>
          </div>
        </div>
      </div>
    </div>
  )

  const renderAddUserView = () => (
    <div className="animate-fade-in max-w-2xl mx-auto py-10">
      <div className="bg-[#EEF4E4] rounded-[2.5rem] p-10 md:p-14 shadow-sm border border-white/40">
        <h3 className="text-3xl font-bold font-headline text-[#4A6B10] mb-10">Invite New Member</h3>
        <div className="space-y-8">
          <div>
            <label className="block text-sm font-bold text-[#4A6B10] mb-2 px-1">Full Name</label>
            <input
              type="text"
              value={addUserForm.full_name}
              onChange={(e) => setAddUserForm({ ...addUserForm, full_name: e.target.value })}
              className="w-full bg-[#FBFBF5] border-none rounded-full px-6 py-3.5 shadow-inner font-medium"
            />
          </div>
          <div>
            <label className="block text-sm font-bold text-[#4A6B10] mb-2 px-1">
              Email Address
            </label>
            <input
              type="email"
              value={addUserForm.email}
              onChange={(e) => setAddUserForm({ ...addUserForm, email: e.target.value })}
              className="w-full bg-[#FBFBF5] border-none rounded-full px-6 py-3.5 shadow-inner font-medium"
            />
          </div>
          <div>
            <label className="block text-sm font-bold text-[#4A6B10] mb-2 px-1">
              Initial Points (Optional)
            </label>
            <input
              type="number"
              value={addUserForm.points}
              onChange={(e) => setAddUserForm({ ...addUserForm, points: e.target.value })}
              className="w-full bg-[#FBFBF5] border-none rounded-full px-6 py-3.5 shadow-inner font-medium"
            />
          </div>
          <div className="flex gap-4 pt-6">
            <button
              onClick={handleCreateUser}
              disabled={loading}
              className="flex-1 bg-[#426500] text-white font-bold py-4 rounded-full shadow-md hover:bg-[#4a6b10] transition-all"
            >
              {loading ? 'Processing...' : 'Send Invitation'}
            </button>
            <button
              onClick={() => setViewMode('list')}
              className="flex-1 bg-white border-2 border-[#D1D3C8] text-on-surface-variant font-bold py-4 rounded-full transition-all"
            >
              Cancel
            </button>
          </div>
        </div>
      </div>
    </div>
  )

  const renderUserDetails = () => {
    const status = getStatusBadge(selectedUser?.points_balance || 0)
    return (
      <div className="animate-fade-in space-y-6">
        <div className="flex gap-6 mb-2">
          <button
            onClick={() => setDetailTab('details')}
            className={`text-xl font-bold font-headline transition-all ${detailTab === 'details' ? 'text-primary underline underline-offset-8 decoration-2' : 'text-on-surface-variant opacity-60'}`}
          >
            User Details
          </button>
          <button
            onClick={() => setDetailTab('points')}
            className={`text-xl font-bold font-headline transition-all ${detailTab === 'points' ? 'text-primary underline underline-offset-8 decoration-2' : 'text-on-surface-variant opacity-60'}`}
          >
            Points Dashboard
          </button>
        </div>
        <div className="bg-[#F2F3EB]/50 rounded-[2.5rem] p-12 shadow-sm border border-outline-variant/30 max-w-4xl min-h-[440px]">
          {detailTab === 'details' ? (
            <div className="space-y-10 max-w-lg animate-fade-in pt-4">
              <div className="flex gap-4">
                <div className="flex-grow">
                  <label className="block text-[10px] font-black text-[#4A6B10]/40 uppercase tracking-[0.2em] mb-2 px-1">
                    First Name
                  </label>
                  <input
                    type="text"
                    value={editUserForm.first_name}
                    onChange={(e) =>
                      setEditUserForm({ ...editUserForm, first_name: e.target.value })
                    }
                    className="w-full bg-white border-none rounded-2xl px-6 py-4 shadow-sm font-medium text-lg"
                  />
                </div>
                <div className="flex-grow">
                  <label className="block text-[10px] font-black text-[#4A6B10]/40 uppercase tracking-[0.2em] mb-2 px-1">
                    Last Name
                  </label>
                  <input
                    type="text"
                    value={editUserForm.last_name}
                    onChange={(e) =>
                      setEditUserForm({ ...editUserForm, last_name: e.target.value })
                    }
                    className="w-full bg-white border-none rounded-2xl px-6 py-4 shadow-sm font-medium text-lg"
                  />
                </div>
              </div>
              <div>
                <label className="block text-[10px] font-black text-[#4A6B10]/40 uppercase tracking-[0.2em] mb-2 px-1">
                  Email Connection
                </label>
                <input
                  type="email"
                  value={editUserForm.email}
                  onChange={(e) => setEditUserForm({ ...editUserForm, email: e.target.value })}
                  className="w-full bg-white border-none rounded-2xl px-6 py-4 shadow-sm font-medium text-lg"
                />
              </div>
              <div className="pt-4">
                <button className="bg-primary text-white font-bold py-4 px-16 rounded-full shadow-lg shadow-primary/20 hover:bg-[#395800] transition-all active:scale-95 uppercase text-xs tracking-widest">
                  Update Profile
                </button>
              </div>
            </div>
          ) : (
            <div className="animate-fade-in pt-4">
              <div className="bg-white rounded-[2.5rem] p-10 md:p-12 mb-10 flex flex-col md:flex-row justify-between items-center gap-8 shadow-sm">
                <div className="text-center md:text-left">
                  <h4 className="text-5xl font-black text-primary font-headline mb-2">
                    {selectedUser?.points_balance || 0}
                  </h4>
                  <p className="text-on-surface-variant/40 font-bold text-xs tracking-widest uppercase">
                    Current Points Balance
                  </p>
                </div>
                <div
                  className={`px-8 py-3 rounded-full ${status.class} font-black text-xs tracking-[0.2em]`}
                >
                  {status.label} STATUS
                </div>
              </div>
              <div className="bg-primary/5 rounded-[2.5rem] p-10 border border-primary/10">
                <h5 className="text-sm font-bold text-primary mb-6 flex items-center gap-2">
                  <span className="material-symbols-outlined text-[18px]">add_moderator</span>Manual
                  Point Adjustment
                </h5>
                <div className="flex gap-4">
                  <div className="relative flex-grow">
                    <input
                      type="number"
                      value={manualPointsAmount}
                      onChange={(e) => setManualPointsAmount(e.target.value)}
                      placeholder="Enter amount..."
                      className="w-full bg-white border-none rounded-full px-6 py-4 shadow-inner font-bold text-lg outline-none"
                    />
                    <span className="absolute right-6 top-1/2 -translate-y-1/2 text-[10px] font-black text-primary/30 uppercase tracking-widest">
                      Points
                    </span>
                  </div>
                  <button
                    onClick={handleManualAddPoints}
                    disabled={loading || !manualPointsAmount}
                    className="bg-primary text-white font-bold py-4 px-12 rounded-full shadow-md hover:bg-[#395800] transition-all active:scale-95 disabled:opacity-20 whitespace-nowrap"
                  >
                    {loading ? '...' : 'Add Points'}
                  </button>
                </div>
              </div>
            </div>
          )}
          <div className="flex justify-end gap-3 mt-12 pb-2">
            <button
              onClick={() => setShowDeleteModal(true)}
              className="bg-[#426500] text-white font-bold py-3 px-12 text-xs tracking-[0.1em] rounded-full shadow-md hover:bg-[#4a6b10] transition-all"
            >
              DELETE USER
            </button>
            <button
              onClick={() => setViewMode('list')}
              className="bg-white border-2 border-[#D1D3C8] text-on-surface-variant/80 font-bold py-3 px-14 text-xs tracking-[0.1em] rounded-full hover:bg-surface-container-highest/20 transition-all"
            >
              EXIT
            </button>
          </div>
        </div>
      </div>
    )
  }

  const renderUserList = () => (
    <div className="animate-fade-in space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-center gap-6">
        <div className="relative w-full max-w-xl">
          <input
            type="text"
            placeholder="Search members, emails..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full bg-[#F2F3EB] border-none rounded-full px-12 py-3.5 shadow-inner focus:ring-2 focus:ring-primary/20 transition-all font-medium text-on-surface-variant"
          />
          <span className="material-symbols-outlined absolute left-4 top-3.5 text-on-surface-variant/40">
            search
          </span>
        </div>
        <button
          onClick={() => setViewMode('add-user')}
          className="bg-[#426500] text-white font-bold py-3.5 px-8 rounded-full shadow-md hover:bg-[#4a6b10] transition-all flex items-center gap-2 whitespace-nowrap"
        >
          <span className="material-symbols-outlined text-[18px]">person_add</span>
          <span className="text-xs uppercase tracking-widest">Invite New</span>
        </button>
      </div>
      <div className="bg-[#EEF4E4]/40 rounded-[2.5rem] md:rounded-[2.5rem] p-4 md:p-8 shadow-sm border border-outline-variant/20">
        <div className="bg-white rounded-[1.5rem] md:rounded-[2rem] overflow-hidden border border-primary/5 shadow-sm">
          <div className="overflow-x-auto">
            <table className="w-full text-left min-w-[800px] lg:min-w-full">
              <thead className="bg-[#F2F3EB]/30 border-b border-primary/5">
                <tr>
                  <th className="px-8 py-5 text-sm font-bold text-[#4A6B10] opacity-80 whitespace-nowrap">
                    Member Name
                  </th>
                  <th className="px-8 py-5 text-sm font-bold text-[#4A6B10] opacity-80 whitespace-nowrap">
                    Email Address
                  </th>
                  <th className="px-8 py-5 text-sm font-bold text-[#4A6B10] opacity-80 text-center whitespace-nowrap">
                    Points Balance
                  </th>
                  <th className="px-8 py-5 text-sm font-bold text-[#4A6B10] opacity-80 text-center whitespace-nowrap">
                    Status
                  </th>
                  <th className="px-8 py-5 text-sm font-bold text-[#4A6B10] opacity-80 text-right whitespace-nowrap">
                    Actions
                  </th>
                </tr>
              </thead>
              <tbody className="divide-y divide-[#426500]/5 transition-all">
                {filteredUsers.length > 0 ? (
                  filteredUsers.map((u) => {
                    const status = getStatusBadge(u.points_balance)
                    return (
                      <tr
                        key={u.id}
                        className="hover:bg-[#EEF4E4]/30 transition-colors group cursor-pointer"
                        onClick={() => {
                          setSelectedUser(u)
                          setViewMode('user-details')
                        }}
                      >
                        <td className="px-8 py-5 text-[15px] font-bold text-primary font-headline">
                          {u.first_name} {u.last_name}
                        </td>
                        <td className="px-8 py-5 text-sm font-medium text-on-surface-variant/80 italic">
                          {u.email}
                        </td>
                        <td className="px-8 py-5 text-sm font-bold text-[#4A6B10] text-center font-headline">
                          {u.points_balance} pts
                        </td>
                        <td className="px-8 py-5 text-center">
                          <span
                            className={`inline-block px-4 py-1 rounded-full text-[9px] font-bold tracking-widest ${status.class}`}
                          >
                            {status.label}
                          </span>
                        </td>
                        <td className="px-8 py-5 text-right">
                          <span className="bg-[#426500]/10 text-[#426500] font-bold text-[10px] tracking-widest px-4 py-1.5 rounded-full border border-[#426500]/20 group-hover:bg-[#426500] group-hover:text-white transition-all uppercase">
                            View Member
                          </span>
                        </td>
                      </tr>
                    )
                  })
                ) : (
                  <tr>
                    <td
                      colSpan="5"
                      className="px-8 py-12 text-center text-on-surface-variant/40 italic font-medium"
                    >
                      No members match your search criteria.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  )

  const renderGiveawaysGridView = () => {
    const current = giveaways.filter((g) => g.active)
    const upcoming = giveaways.filter((g) => !g.active)
    return (
      <div className="space-y-12">
        <div className="flex justify-between items-center mb-4">
          <h3 className="text-[11px] font-black text-on-surface-variant/60 uppercase tracking-[0.3em]">
            Live Now
          </h3>
          <button
            onClick={() => {
              setEditingGiveaway({
                title: '',
                participation_conditions: '',
                start_date: '',
                end_date: '',
                active: true,
              })
              setGiveawayMode('edit')
            }}
            className="bg-[#426500] text-white font-bold py-2.5 px-6 rounded-full text-xs shadow-md hover:bg-[#4a6b10] transition-all flex items-center gap-2 uppercase tracking-widest"
          >
            Create New
          </button>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {current.map((g) => (
            <div
              key={g.id}
              onClick={() => {
                setEditingGiveaway(g)
                setGiveawayMode('edit')
              }}
              className="bg-white rounded-[2.5rem] p-8 shadow-sm border border-primary/10 hover:shadow-xl hover:-translate-y-1 transition-all cursor-pointer group flex flex-col justify-between min-h-[220px]"
            >
              <div>
                <div className="flex justify-between items-start mb-4">
                  <span className="bg-[#EEF4E4] text-[#4A6B10] text-[9px] font-black px-3 py-1 rounded-full tracking-widest uppercase">
                    Ongoing
                  </span>
                  <span className="material-symbols-outlined text-primary/30 group-hover:text-primary transition-colors">
                    edit_square
                  </span>
                </div>
                <h4 className="text-2xl font-bold font-headline text-[#1a2a00] mb-2">{g.title}</h4>
              </div>
              <div className="text-[10px] font-bold text-on-surface-variant/40 uppercase tracking-widest mt-6">
                Ends: {new Date(g.end_date).toLocaleDateString()}
              </div>
            </div>
          ))}
        </div>
      </div>
    )
  }

  const renderLocationsGridView = () => (
    <div className="space-y-12">
      <div className="flex justify-between items-center mb-4">
        <h3 className="text-[11px] font-black text-on-surface-variant/60 uppercase tracking-[0.3em]">
          Our Stores
        </h3>
        <button
          onClick={() => {
            setEditingLocation({
              name: '',
              address_line_1: '',
              suburb: '',
              state: '',
              postcode: '',
              map_url: '',
              active: true,
            })
            setLocationMode('edit')
          }}
          className="bg-[#426500] text-white font-bold py-2.5 px-6 rounded-full text-xs shadow-md uppercase tracking-widest"
        >
          Add Store
        </button>
      </div>
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
        {locations.map((loc) => (
          <div
            key={loc.id}
            onClick={() => {
              setEditingLocation(loc)
              setLocationMode('edit')
            }}
            className="bg-[#EEF4E4]/40 rounded-[2.5rem] p-8 border border-white/60 hover:shadow-lg transition-all cursor-pointer relative group"
          >
            <h4 className="text-xl font-bold font-headline text-[#4A6B10] mb-4">{loc.name}</h4>
            <p className="text-sm font-medium text-on-surface-variant/70 leading-relaxed mb-1">
              {loc.address_line_1}
            </p>
            <p className="text-sm font-bold text-primary/60">
              {loc.suburb}, {loc.state} {loc.postcode}
            </p>
            <span className="material-symbols-outlined absolute top-8 right-8 text-primary/20 group-hover:text-primary transition-colors">
              location_on
            </span>
          </div>
        ))}
      </div>
    </div>
  )

  return (
    <div className="bg-[#fbfcfa] min-h-screen text-on-surface">
      <SideNavbar activeTab={activeTab} setActiveTab={setActiveTab} onLogout={logout} user={user} />
      <main className="lg:ml-64 p-6 md:p-12 min-h-screen">
        <AdminHeader
          title={navItems.find((item) => item.id === activeTab)?.label || 'System Admin'}
          subtitle="Curate your community rewards and manage loyalty points with editorial precision."
          activeTab={activeTab}
          onTabChange={(tab) => {
            setActiveTab(tab)
            setViewMode('list')
            setGiveawayMode('grid')
            setLocationMode('grid')
          }}
        />
        <div className="mt-12">
          {activeTab === 'dashboard' && (
            <>
              {viewMode === 'list' && renderUserList()}
              {viewMode === 'add-user' && renderAddUserView()}
              {viewMode === 'user-details' && selectedUser && renderUserDetails()}
            </>
          )}
          {activeTab === 'bonus-entry' && (
            <BonusEntryForm
              users={users}
              onQuickAdd={handleQuickPoints}
              loading={loading}
              token={token}
            />
          )}
          {activeTab === 'giveaways' && (
            <div className="animate-fade-in">
              {giveawayMode === 'grid' ? (
                renderGiveawaysGridView()
              ) : (
                <GiveawayEditor
                  giveaway={editingGiveaway}
                  onSave={handleSaveGiveaway}
                  onCancel={() => setGiveawayMode('grid')}
                  onDelete={handleDeleteGiveaway}
                  loading={loading}
                  token={token}
                />
              )}
            </div>
          )}
          {activeTab === 'locations' && (
            <div className="animate-fade-in">
              {locationMode === 'grid' ? (
                renderLocationsGridView()
              ) : (
                <LocationEditor
                  location={editingLocation}
                  onSave={handleSaveLocation}
                  onCancel={() => setLocationMode('grid')}
                  onDelete={handleDeleteLocation}
                  loading={loading}
                />
              )}
            </div>
          )}
          {activeTab === 'links' && <WebsiteLinksForm />}
        </div>
        <FooterAdmin />
      </main>
      {showDeleteModal && renderDeleteModal()}
    </div>
  )
}

export default AdminDashboard

