import { useState, useEffect } from 'react'
import { useNavigate } from 'react-router-dom'
import { useAuth } from '../context/AuthContext'
import { useToast } from '../context/ToastContext'
import { updateProfile } from '../api/auth'
import { CustomDatePicker } from '../components/Common/SharedUI'

function CustomerDashboard() {
  const { user, token, updateUser, logout } = useAuth()
  const { showToast } = useToast()
  const navigate = useNavigate()

  // View state: 'dashboard', 'rewards', 'giveaways', 'reward-details', 'edit-account'
  const [activeTab, setActiveTab] = useState('dashboard')
  const [loading, setLoading] = useState(false)
  const [saveStatus, setSaveStatus] = useState('')
  const [giveaways, setGiveaways] = useState([])
  const [localParticipation, setLocalParticipation] = useState([])
  const [lastUpdate, setLastUpdate] = useState(Date.now())

  const refreshAllData = async () => {
    setLoading(true)
    await fetchGiveawaysData()
    // If we had a way to refresh the user profile points, we'd do it here too
    // For now, giveaways is the primary reactive data
    setLoading(false)
  }

  const fetchGiveawaysData = async () => {
    if (!token) return
    try {
      const timestamp = new Date().getTime()
      const gRes = await fetch(`/api/giveaways?t=${timestamp}`, {
        headers: { Authorization: `Bearer ${token}` },
      })
      if (!gRes.ok) throw new Error('API request failed')
      const gData = await gRes.json()
      const syncedData = Array.isArray(gData) ? gData : []

      // Merge server data but PROTECT current optimistic updates if they are newer
      setGiveaways((prev) => {
        return syncedData.map((newG) => {
          const localG = prev.find((p) => Number(p.id) === Number(newG.id))
          // If we locally marked it as joined, keep it joined even if server is lagging
          if (localG?.isJoined && !newG.isJoined) {
            return { ...newG, isJoined: true }
          }
          return newG
        })
      })
      setLastUpdate(Date.now())
    } catch (err) {
      console.error('Failed to fetch giveaway data:', err)
    }
  }

  useEffect(() => {
    if (token) fetchGiveawaysData()
  }, [token])

  const handleTabClick = (tab) => {
    setActiveTab(tab)
    refreshAllData()
  }

  const getStatusBadge = (points) => {
    if (points >= 1500) return { label: 'PLATINUM', class: 'bg-[#4A6B10] text-white shadow-md' }
    if (points >= 1000) return { label: 'GOLD', class: 'bg-primary text-white shadow-sm' }
    if (points >= 500) return { label: 'SILVER', class: 'bg-[#DFEECA] text-[#4A6B10]' }
    return { label: 'BRONZE', class: 'bg-[#EEF4E4] text-[#4A6B10]/60' }
  }

  const status = getStatusBadge(user?.points_balance || 0)

  // Form state
  const [formData, setFormData] = useState({
    first_name: user?.first_name || '',
    last_name: user?.last_name || '',
    email: user?.email || '',
    phone: user?.phone || '',
    date_of_birth: user?.date_of_birth || '',
  })

  // Punch Card Logic: 1 punch per 200 points, 6 punches = reward
  const POINTS_PER_PUNCH = 200
  const totalPunches = 6
  const currentPunches = Math.floor((user?.points_balance || 0) / POINTS_PER_PUNCH) % totalPunches
  const moreToGo = totalPunches - currentPunches

  const handleSave = async () => {
    setLoading(true)
    setSaveStatus('')
    try {
      const updatedUser = await updateProfile(formData, token)
      updateUser(updatedUser)
      setSaveStatus('success')
      setTimeout(() => setSaveStatus(''), 3000)
    } catch (err) {
      console.error(err)
      setSaveStatus('error')
    } finally {
      setLoading(false)
    }
  }

  // Reusable header navigation
  const renderHeader = () => (
    <header
      className={`flex justify-between items-center py-8 mb-6 border-outline-variant/10 ${activeTab === 'edit-account' ? 'border-b-0' : 'border-b'}`}
    >
      <div className="text-3xl font-headline font-bold text-primary">Kem Boi</div>

      {activeTab !== 'edit-account' && (
        <>
          <div className="hidden md:flex gap-10 text-[15px] font-semibold mt-2">
            <div
              className="relative group cursor-pointer"
              onClick={() => handleTabClick('dashboard')}
            >
              <span
                className={`transition-colors ${activeTab === 'dashboard' ? 'text-primary font-bold' : 'text-on-surface-variant hover:text-primary'}`}
              >
                Dashboard
              </span>
              {activeTab === 'dashboard' && (
                <div className="absolute left-0 bottom-[-4px] w-full h-[3px] bg-primary"></div>
              )}
            </div>

            <div
              className="relative group cursor-pointer"
              onClick={() => handleTabClick('rewards')}
            >
              <span
                className={`transition-colors ${activeTab === 'rewards' || activeTab === 'reward-details' ? 'text-primary font-bold' : 'text-on-surface-variant hover:text-primary'}`}
              >
                Rewards
              </span>
              {activeTab === 'rewards' || activeTab === 'reward-details' ? (
                <div className="absolute left-0 bottom-[-4px] w-full h-[3px] bg-primary"></div>
              ) : null}
            </div>

            <div
              className="relative group cursor-pointer"
              onClick={() => handleTabClick('giveaways')}
            >
              <span
                className={`transition-colors ${activeTab === 'giveaways' ? 'text-primary font-bold' : 'text-on-surface-variant hover:text-primary'}`}
              >
                Giveaways
              </span>
              {activeTab === 'giveaways' && (
                <div className="absolute left-0 bottom-[-4px] w-full h-[3px] bg-primary"></div>
              )}
            </div>
          </div>

          <div className="flex items-center gap-4">
            <div
              onClick={() => setActiveTab('edit-account')}
              className="flex items-center gap-3 bg-white/40 pr-4 pl-1 py-1 rounded-full border border-white/60 cursor-pointer hover:bg-white/60 transition-colors shadow-sm"
            >
              <div className="w-10 h-10 rounded-full bg-primary flex items-center justify-center text-[#e8ebe3] font-bold">
                <span className="material-symbols-outlined text-[1.2rem]">person</span>
              </div>
              <div className="flex flex-col">
                <span className="text-sm font-bold text-primary leading-tight">
                  {user?.first_name ? `${user.first_name} ${user.last_name || ''}` : 'Full Name'}
                </span>
                <span className="text-xs text-on-surface-variant/70 leading-tight capitalize">
                  {user?.role || 'Member'}
                </span>
              </div>
            </div>

            <button
              onClick={() => {
                logout()
                navigate('/')
              }}
              className="w-10 h-10 rounded-full bg-white/40 flex items-center justify-center text-primary border border-white/60 hover:bg-red-50 hover:text-red-600 transition-colors shadow-sm"
              title="Logout"
            >
              <span className="material-symbols-outlined text-[1.2rem] pointer-events-none">
                logout
              </span>
            </button>
          </div>
        </>
      )}
    </header>
  )

  const renderBottomNav = () => (
    <div className="fixed bottom-0 left-0 w-full bg-[#fcfdf9]/90 backdrop-blur-md border-t border-outline-variant/10 px-6 py-3 flex justify-around items-center md:hidden z-50">
      <button
        onClick={() => handleTabClick('dashboard')}
        className={`flex flex-col items-center gap-1 transition-colors ${activeTab === 'dashboard' ? 'text-primary' : 'text-on-surface-variant/60'}`}
      >
        <span className="material-symbols-outlined text-[24px]">home</span>
        <span className="text-[10px] font-bold uppercase tracking-widest">Home</span>
      </button>

      <button
        onClick={() => handleTabClick('rewards')}
        className={`flex flex-col items-center gap-1 transition-colors ${activeTab === 'rewards' || activeTab === 'reward-details' ? 'text-primary' : 'text-on-surface-variant/60'}`}
      >
        <span className="material-symbols-outlined text-[24px]">emoji_events</span>
        <span className="text-[10px] font-bold uppercase tracking-widest">Rewards</span>
      </button>

      <button
        onClick={() => handleTabClick('giveaways')}
        className={`flex flex-col items-center gap-1 transition-colors ${activeTab === 'giveaways' ? 'text-primary' : 'text-on-surface-variant/60'}`}
      >
        <span className="material-symbols-outlined text-[24px]">redeem</span>
        <span className="text-[10px] font-bold uppercase tracking-widest">WINS</span>
      </button>

      <button
        onClick={() => setActiveTab('edit-account')}
        className={`flex flex-col items-center gap-1 transition-colors ${activeTab === 'edit-account' ? 'text-primary' : 'text-on-surface-variant/60'}`}
      >
        <span className="material-symbols-outlined text-[24px]">person</span>
        <span className="text-[10px] font-bold uppercase tracking-widest">Profile</span>
      </button>
    </div>
  )

  const handleEnterGiveaway = async (giveawayId) => {
    try {
      const res = await fetch(`/api/giveaways/${giveawayId}/enter`, {
        method: 'POST',
        headers: { Authorization: `Bearer ${token}` },
      })
      if (res.ok) {
        showToast('Successfully entered giveaway!', 'success')

        // Step 1: Mark it in local participation list INSTANTLY
        setLocalParticipation((prev) => [...prev, Number(giveawayId)])

        // Step 2: Force local state update for giveaways array
        setGiveaways((prev) => {
          return prev.map((g) =>
            Number(g.id) === Number(giveawayId) ? { ...g, isJoined: true } : g
          )
        })
        setLastUpdate(Date.now())

        // Step 3: Background Sync - but the local list will "Shield" the UI now
        setTimeout(() => fetchGiveawaysData(), 1500)
      } else if (res.status === 422) {
        showToast('You are already participating!', 'success')
        setLocalParticipation((prev) => [...prev, Number(giveawayId)])
        setLastUpdate(Date.now())
        fetchGiveawaysData()
      } else {
        const data = await res.json()
        showToast(data.error || 'Failed to enter giveaway', 'error')
      }
    } catch (err) {
      showToast('Network error', 'error')
    }
  }

  const renderDashboard = () => (
    <div className="space-y-6 animate-fade-in">
      {/* Welcome Banner */}
      <div className="bg-[#DFEECA] rounded-[1.5rem] p-8 md:p-10 shadow-sm border border-white/40">
        <h1 className="text-3xl md:text-4xl font-headline font-bold text-primary mb-3">
          Welcome to your Kem Boi Dashboard, {user?.first_name || 'Family member'}!
        </h1>
        <p className="text-on-surface-variant font-medium text-lg md:text-xl opacity-80">
          Stay on top of your rewards, and never miss a giveaway.
        </p>
      </div>

      {/* Main Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Points Balance */}
        <div className="bg-primary rounded-[2.5rem] p-8 md:p-10 text-white shadow-xl flex flex-col justify-between relative overflow-hidden group">
          <div className="relative z-10">
            <div className="flex justify-between items-start mb-4">
              <h2 className="text-2xl font-bold font-headline">Points Balance:</h2>
              <span
                className={`px-5 py-1.5 rounded-full text-[10px] font-bold tracking-widest ${status.class} shadow-lg shadow-black/10 transition-transform active:scale-95`}
              >
                {status.label}
              </span>
            </div>
            <div className="text-6xl sm:text-7xl md:text-[5.5rem] font-bold font-headline text-center my-8 tracking-tighter text-[#e7eed8] drop-shadow-sm group-hover:scale-105 transition-transform duration-500">
              {user?.points_balance || 0} pt
              <span className="text-4xl sm:text-5xl md:text-6xl">s</span>
            </div>
          </div>
          <p className="text-base font-semibold leading-relaxed opacity-90 mt-4 max-w-[280px] relative z-10 italic">
            "Keep sipping, you're only{' '}
            {status.label === 'PLATINUM'
              ? 'mastering the art'
              : status.label === 'GOLD'
                ? '500 pts'
                : 'a few drinks'}{' '}
            away from the next tier!"
          </p>

          {/* Subtle background decoration */}
          <div className="absolute top-[-20%] right-[-10%] w-64 h-64 bg-white/5 rounded-full blur-3xl group-hover:bg-white/10 transition-colors"></div>
        </div>

        {/* Punch Card Tracker */}
        <div className="bg-primary rounded-[1.5rem] p-8 md:p-10 text-white shadow-md flex flex-col justify-between">
          <div>
            <h2 className="text-3xl md:text-4xl font-bold font-headline mb-2">Buy 5, Get 1 Free</h2>
            <p className="text-lg font-medium opacity-90 mb-8 font-headline">
              {moreToGo === 0
                ? 'Reward Ready to Claim!'
                : `Only ${moreToGo} more punch${moreToGo > 1 ? 'es' : ''} to go!`}
            </p>

            {/* Punch circles */}
            <div className="flex justify-between items-center gap-3 mb-10">
              {[1, 2, 3, 4, 5, 6].map((idx) => (
                <div
                  key={idx}
                  className={`h-4 lg:h-5 flex-1 rounded-full shadow-inner ${idx <= currentPunches ? 'bg-[#c3e68c]' : 'bg-[#e2ead3]'}`}
                ></div>
              ))}
            </div>
          </div>

          <div className="flex justify-center">
            <button
              disabled={moreToGo > 0}
              className={`font-bold py-3.5 px-10 rounded-full text-lg tracking-wide transition-all ${moreToGo === 0 ? 'bg-[#c3e68c] text-primary shadow-lg hover:scale-105 active:scale-95' : 'bg-[#d5dfc5] text-primary/40 cursor-not-allowed'}`}
            >
              {moreToGo === 0 ? 'Claim Reward' : 'Claim Offer'}
            </button>
          </div>
        </div>
      </div>

      {/* Action Links Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mt-4">
        <div
          onClick={() => handleTabClick('rewards')}
          className="bg-transparent border border-outline-variant/30 rounded-[1.5rem] p-8 shadow-sm flex justify-between items-start cursor-pointer hover:bg-[#e0e2d6]/50 transition-colors group"
        >
          <div className="pr-4">
            <h3 className="text-primary font-bold font-headline text-2xl mb-3 group-hover:underline">
              Claim Your Rewards
            </h3>
            <p className="text-base text-on-surface-variant/80 font-medium">
              View and redeem your rewards here.
            </p>
          </div>
          <span className="material-symbols-outlined text-[2rem] text-primary">emoji_events</span>
        </div>

        <div
          onClick={() => handleTabClick('giveaways')}
          className="bg-transparent border border-outline-variant/30 rounded-[1.5rem] p-8 shadow-sm flex justify-between items-start cursor-pointer hover:bg-[#e0e2d6]/50 transition-colors group"
        >
          <div className="pr-4">
            <h3 className="text-primary font-bold font-headline text-2xl mb-3 group-hover:underline">
              Win a Free Kem Boi Tote Bag
            </h3>
            <p className="text-base text-on-surface-variant/80 font-medium">
              Keep up to date with current and upcoming giveaways here.
            </p>
          </div>
          <span className="material-symbols-outlined text-[2rem] text-primary">redeem</span>
        </div>
      </div>
    </div>
  )

  const ParticipationButton = ({ giveaway }) => {
    const isJoined = giveaway.isJoined || localParticipation.includes(Number(giveaway.id))

    if (isJoined) {
      return (
        <div className="flex items-center gap-2 bg-[#EEF4E4] text-[#4A6B10] font-bold py-2 px-5 text-[11px] tracking-widest rounded-full border border-[#4A6B10]/20 shadow-inner min-w-[100px] justify-center">
          <span className="material-symbols-outlined text-[14px]">check_circle</span>
          JOINED
        </div>
      )
    }

    return (
      <button
        onClick={(e) => {
          e.stopPropagation()
          handleEnterGiveaway(giveaway.id)
        }}
        className="bg-primary text-white font-bold py-2 px-8 text-[11px] tracking-widest rounded-full hover:bg-[#395800] transition-colors shadow-sm active:scale-95 min-w-[100px]"
      >
        ENTER
      </button>
    )
  }

  const renderGiveaways = () => {
    console.log(
      'Rendering Giveaways. Local:',
      localParticipation,
      'Server State Check:',
      giveaways.map((g) => `${g.id}:${g.isJoined}`)
    )
    const activeGiveaways = giveaways.filter((g) => g.active)
    const upcomingGiveaways = giveaways.filter((g) => !g.active)

    return (
      <div key={`giveaways-container-${lastUpdate}`} className="space-y-10 animate-fade-in pb-12">
        <div>
          <h2 className="text-xl font-bold font-headline text-on-surface mb-6">
            Current Giveaways
          </h2>
          <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-6">
            {activeGiveaways.length === 0 ? (
              <p className="text-on-surface-variant/60 font-medium col-span-full">
                No active giveaways at the moment. Check back soon!
              </p>
            ) : (
              activeGiveaways.map((g) => (
                <div
                  key={`${g.id}-${g.isJoined}`}
                  className="bg-[#E4ECD5] rounded-2xl p-6 shadow-sm flex flex-col border border-white/20 min-h-[180px]"
                >
                  <div className="flex justify-between items-start mb-3">
