export default CustomerDashboard

import { useState, useEffect } from 'react'
import { useAuth } from '../../context/AuthContext'
import { useToast } from '../../context/ToastContext'
import { CustomDatePicker, ModernConfirm } from '../Common/SharedUI'

function RewardsManager({ onRewardsChange }) {
  const { token } = useAuth()
  const { showToast } = useToast()
  const [rewards, setRewards] = useState([])
  const [editingReward, setEditingReward] = useState(null)
  const [loading, setLoading] = useState(false)
  const [showNewReward, setShowNewReward] = useState(false)
  const [showConfirm, setShowConfirm] = useState(false)
  const [rewardToDelete, setRewardToDelete] = useState(null)

  const [rewardData, setRewardData] = useState({
    name: '',
    description: '',
    point_cost: 0,
    active: true,
    start_date: '',
    end_date: '',
    limit_per_user: 0,
    total_limit: 0,
  })

  const fetchRewards = async () => {
    try {
      const res = await fetch('/api/rewards', {
        headers: { Authorization: `Bearer ${token}` },
      })
      const data = await res.json()
      setRewards(Array.isArray(data) ? data : [])
    } catch (err) {
      console.error(err)
    }
  }

  useEffect(() => {
    fetchRewards()
  }, [token])

  const handleSaveReward = async () => {
    if (!rewardData.name.trim()) {
      showToast('Reward name is required', 'error')
      return
    }

    setLoading(true)
    const url = editingReward ? `/api/rewards/${editingReward.id}` : '/api/rewards'
    const method = editingReward ? 'PUT' : 'POST'

    try {
      const res = await fetch(url, {
        method,
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ reward: rewardData }),
      })

      if (res.ok) {
        showToast(editingReward ? 'Reward updated!' : 'Reward created!', 'success')
        fetchRewards()
        if (onRewardsChange) onRewardsChange()
        cancelEdit()
      } else {
        const errData = await res.json()
        const errMsg = errData
          ? Object.entries(errData)
              .map(([k, v]) => `${k} ${v}`)
              .join(', ')
          : 'Operation failed'
        showToast(errMsg, 'error')
      }
    } catch (err) {
      showToast('Network error occurred', 'error')
    } finally {
      setLoading(false)
    }
  }

  const handleDeleteReward = (id) => {
    setRewardToDelete(id)
    setShowConfirm(true)
  }

  const confirmDelete = async () => {
    if (!rewardToDelete) return

    try {
      const res = await fetch(`/api/rewards/${rewardToDelete}`, {
        method: 'DELETE',
        headers: { Authorization: `Bearer ${token}` },
      })
      if (res.ok) {
        showToast('Reward deleted', 'info')
        fetchRewards()
        if (onRewardsChange) onRewardsChange()
        cancelEdit() // Return to dashboard list
      }
    } catch (err) {
      console.error(err)
      showToast('Failed to delete', 'error')
    } finally {
      setShowConfirm(false)
      setRewardToDelete(null)
    }
  }

  const cancelEdit = () => {
    setEditingReward(null)
    setShowNewReward(false)
    setRewardData({
      name: '',
      description: '',
      point_cost: 0,
      active: true,
      start_date: '',
      end_date: '',
      limit_per_user: 0,
      total_limit: 0,
    })
  }

  const startEdit = (reward) => {
    setEditingReward(reward)
    setRewardData({
      name: reward.name,
      description: reward.description,
      point_cost: reward.point_cost,
      active: reward.active,
      start_date: reward.start_date || '',
      end_date: reward.end_date || '',
      limit_per_user: reward.limit_per_user || 0,
      total_limit: reward.total_limit || 0,
    })
    setShowNewReward(true)
  }

  return (
    <div className="animate-fade-in space-y-10">
      {showNewReward ? (
        <div className="bg-[#EEF4E4] rounded-[1.5rem] md:rounded-[2.5rem] p-6 md:p-10 shadow-sm border border-white/40 max-w-2xl">
          <h3 className="text-2xl md:text-3xl font-bold font-headline text-[#4A6B10] mb-8">
            {editingReward ? 'Edit Reward' : 'Create New Reward'}
          </h3>
          <div className="space-y-6">
            <div>
              <label className="block text-sm font-bold text-[#4A6B10] mb-2 px-1">
                Reward Name:
              </label>
              <input
                type="text"
                value={rewardData.name}
                onChange={(e) => setRewardData({ ...rewardData, name: e.target.value })}
                placeholder="e.g. Free Avocado Smoothie"
                className="w-full bg-[#FBFBF5] border-none rounded-full px-6 py-4 shadow-inner font-medium text-on-surface focus:ring-2 focus:ring-primary/20 transition-all outline-none"
              />
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-6 md:gap-8">
              <div>
                <label className="block text-sm font-bold text-[#4A6B10] mb-2 px-1">
                  Point Cost:
                </label>
                <input
                  type="number"
                  value={rewardData.point_cost}
                  onChange={(e) =>
                    setRewardData({ ...rewardData, point_cost: parseInt(e.target.value) || 0 })
                  }
                  className="w-full bg-[#FBFBF5] border-none rounded-full px-6 py-4 shadow-inner font-bold text-on-surface focus:ring-2 focus:ring-primary/20 transition-all outline-none"
                />
              </div>
              <div>
                <label className="block text-sm font-bold text-[#4A6B10] mb-2 px-1 text-center font-bold">
                  Limit/User:
                </label>
                <input
                  type="number"
                  value={rewardData.limit_per_user}
                  onChange={(e) =>
                    setRewardData({ ...rewardData, limit_per_user: parseInt(e.target.value) || 0 })
                  }
                  placeholder="0 = ∞"
                  className="w-full bg-[#FBFBF5] border-none rounded-full px-6 py-4 shadow-inner font-bold text-center text-on-surface focus:ring-2 focus:ring-primary/20 transition-all outline-none"
                />
              </div>
              <div>
                <label className="block text-sm font-bold text-[#4A6B10] mb-2 px-1 text-center font-black">
                  Stock Limit:
                </label>
                <input
                  type="number"
                  value={rewardData.total_limit}
                  onChange={(e) =>
                    setRewardData({ ...rewardData, total_limit: parseInt(e.target.value) || 0 })
                  }
                  placeholder="0 = ∞"
                  className="w-full bg-[#FBFBF5] border-none rounded-full px-6 py-4 shadow-inner font-black text-center text-[#4A6B10] focus:ring-2 focus:ring-primary/20 transition-all outline-none"
                />
              </div>
              <div className="flex flex-col justify-end">
                <div className="flex items-center justify-between sm:justify-start gap-4 mb-2 bg-[#FBFBF5]/40 p-2 sm:p-0 rounded-full">
                  <span
                    className={`text-[10px] font-bold uppercase tracking-widest pl-4 sm:pl-0 ${rewardData.active ? 'text-primary' : 'text-on-surface-variant/60'}`}
                  >
                    {rewardData.active ? 'Active' : 'Inactive'}
                  </span>
                  <div
                    onClick={() => setRewardData({ ...rewardData, active: !rewardData.active })}
