      <td className="px-8 py-6 text-center">
        <span
          className={`text-[10px] font-black uppercase tracking-widest px-4 py-1.5 rounded-full border ${
            red.status === 'used' || red.status === 'fulfilled'
              ? 'bg-red-50 text-red-500 border-red-200'
