          }`}
        >
          {red.status}
        </span>
      </td>
      <td className="px-8 py-8 text-right">
        <div className="flex justify-end gap-3">
          {red.status === 'pending' && (
            <button
              onClick={async () => {
                setLoading(true)
                try {
                  await onUpdate(red.id, 'used')
