                          <button
                            onClick={() => setConfirmFulfill({ isOpen: true, reward: r })}
                            className="bg-white border-2 border-[#426500] text-[#426500] font-bold py-2 px-6 rounded-full text-[10px] tracking-widest hover:bg-[#426500] hover:text-white transition-all shadow-sm whitespace-nowrap"
                          >
                            CLAIM & USE
                          </button>
                        </div>
                      ))
                  )}
                </div>
              </div>
            </div>
          </div>
        )}

        <div className="flex flex-col sm:flex-row justify-end gap-3 mt-12 pb-2 px-2 sm:px-0">
          <button
            onClick={() => setShowDeleteModal(true)}
            className="w-full sm:w-auto bg-red-600 text-white font-bold py-3.5 px-12 text-[10px] tracking-[0.2em] rounded-full shadow-md shadow-red-600/10 hover:bg-red-700 transition-all active:scale-95 uppercase"
          >
            Delete Profile
          </button>
          <button
            onClick={() => setViewMode('list')}
            className="w-full sm:w-auto bg-white border-2 border-[#D1D3C8] text-on-surface-variant font-bold py-3.5 px-14 text-[10px] tracking-[0.2em] rounded-full hover:bg-surface-container-highest/20 transition-all uppercase"
          >
            Return to list
          </button>
        </div>

        <ModernConfirm
          isOpen={confirmFulfill.isOpen}
          title={confirmFulfill.redemptionId ? 'Fulfill Voucher?' : 'Manual Fulfillment?'}
          message={
            confirmFulfill.redemptionId
              ? `Confirm usage of voucher "${confirmFulfill.reward?.name}" for this member?`
              : `Are you sure you want to deduct ${confirmFulfill.reward?.point_cost} points from this user and fulfill the "${confirmFulfill.reward?.name}" reward?`
          }
          confirmText={confirmFulfill.redemptionId ? 'Mark as Used' : 'Confirm & Deduct'}
          onConfirm={async () => {
            const { reward, redemptionId } = confirmFulfill
            setConfirmFulfill({ isOpen: false, reward: null, redemptionId: null })
            setLoading(true)
            try {
              if (redemptionId) {
                // Mark as used then immediately delete to "clear" from history as requested
                await onUpdate(redemptionId, 'used')
                await onDelete(redemptionId)

                showToast('Voucher fulfilled and cleared!', 'success')

                // Trigger all refreshes
                await Promise.all([
                  fetchUserRedemptions(selectedUser.id),
                  fetchRedemptions(),
                  fetchUsers(),
                ])
              } else {
                // Create new redemption (Direct Fulfill)
                const res = await fetch(`/api/redemptions/direct_fulfill`, {
                  method: 'POST',
                  headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
                  body: JSON.stringify({ user_id: selectedUser.id, reward_id: reward.id }),
                })
                if (res.ok) {
                  const data = await res.json()
                  showToast('Fulfillment successful!', 'success')
                  // Update user balance immediately
                  setSelectedUser((prev) => ({ ...prev, points_balance: data.user_balance }))

                  // Refresh redemptions and global state
                  await Promise.all([
                    fetchUserRedemptions(selectedUser.id),
                    fetchRedemptions(),
                    fetchUsers(),
                    fetchRewards(),
                  ])
                } else {
                  const errData = await res.json()
                  showToast(
                    errData.error || errData.errors?.join(', ') || 'Manual claim failed',
                    'error'
                  )
                }
              }
            } catch (err) {
              console.error(err)
              showToast('An error occurred during fulfillment', 'error')
            } finally {
              setLoading(false)
            }
          }}
          onCancel={() => setConfirmFulfill({ isOpen: false, reward: null, redemptionId: null })}
        />
      </div>
    </div>
  )
}

import { useState, useEffect } from 'react'
import { useNavigate } from 'react-router-dom'
import { useAuth } from '../context/AuthContext'
import { useToast } from '../context/ToastContext'
import { updateProfile } from '../api/auth'
import { CustomDatePicker, ModernConfirm } from '../components/Common/SharedUI'

function FamilyBonusDashboard() {
  const { user, token, updateUser, logout, refreshProfile } = useAuth()
  const { showToast } = useToast()
  const navigate = useNavigate()

  // View state: 'dashboard', 'rewards', 'reward-details', 'edit-account'
  const [activeTab, setActiveTab] = useState('dashboard')
  const [loading, setLoading] = useState(false)
  const [saveStatus, setSaveStatus] = useState('')
  const [rewards, setRewards] = useState([])
  const [myRedemptions, setMyRedemptions] = useState([])
  const [lastUpdate, setLastUpdate] = useState(Date.now())
  const [confirmData, setConfirmData] = useState({ isOpen: false, reward: null })
  const [selectedReward, setSelectedReward] = useState(null)

  const refreshAllData = async () => {
    setLoading(true)
    await Promise.all([refreshProfile(), fetchRewardsData(), fetchMyRedemptionsData()])
    setLoading(false)
  }

  const fetchRewardsData = async () => {
    if (!token) return
    try {
      const res = await fetch('/api/rewards', {
        headers: { Authorization: `Bearer ${token}` },
      })
      const data = await res.json()
      setRewards(Array.isArray(data) ? data : [])
    } catch (err) {
      console.error('Failed to fetch rewards', err)
    }
  }

  const fetchMyRedemptionsData = async () => {
    if (!token) return
    try {
      const res = await fetch('/api/my_redemptions', {
        headers: { Authorization: `Bearer ${token}` },
      })
      const data = await res.json()
      setMyRedemptions(Array.isArray(data) ? data : [])
    } catch (err) {
      console.error('Failed to fetch my redemptions', err)
    }
  }

  const handleClaimReward = async (reward) => {
    const redemptionCount = myRedemptions.filter(
      (r) => r.reward_id === reward.id || (r.reward && r.reward.id === reward.id)
    ).length
    if (reward.limit_per_user > 0 && redemptionCount >= reward.limit_per_user) {
      showToast(
        `Limit reached: You can only claim this reward ${reward.limit_per_user} time(s).`,
        'error'
      )
      return
    }

    if ((user?.points_balance || 0) < reward.point_cost) {
      showToast(`You need ${reward.point_cost} points to claim this!`, 'error')
      return
    }

    setConfirmData({
      isOpen: true,
      reward,
      message: `Redeem ${reward.point_cost} points for ${reward.name}?`,
    })
    return
  }

  const executeClaimReward = async (reward) => {
    setConfirmData({ isOpen: false, reward: null })
    try {
      const res = await fetch(`/api/rewards/${reward.id}/claim`, {
        method: 'POST',
        headers: { Authorization: `Bearer ${token}` },
      })
      const data = await res.json()
      if (res.ok) {
        showToast(`Success! Your code is: ${data.redemption.voucher_code}`, 'success')
        updateUser({ ...user, points_balance: data.point_balance })
        setActiveTab('vouchers')
        fetchMyRedemptionsData()
      } else {
        showToast(data.error || 'Failed to claim reward', 'error')
      }
    } catch (err) {
      showToast('Network error', 'error')
    }
  }

  useEffect(() => {
    if (token) {
      refreshProfile()
      fetchRewardsData()
      fetchMyRedemptionsData()
    }
  }, [token])

  const handleTabClick = (tab) => {
    setActiveTab(tab)
    refreshAllData()
  }

  const getStatusBadge = (points) => {
    if (points >= 1500) return { label: 'PLATINUM', class: 'bg-[#4A6B10] text-white shadow-md' }
    if (points >= 1000) return { label: 'GOLD', class: 'bg-primary text-white shadow-sm' }
    if (points >= 500) return { label: 'SILVER', class: 'bg-[#DFEECA] text-[#4A6B10]' }
    return { label: 'BRONZE', class: 'bg-[#EEF4E4] text-[#4A6B10]/60' }
  }

  const status = getStatusBadge(user?.points_balance || 0)

  // Form state
  const [formData, setFormData] = useState({
    first_name: user?.first_name || '',
    last_name: user?.last_name || '',
    email: user?.email || '',
    phone: user?.phone || '',
    date_of_birth: user?.date_of_birth || '',
  })

  // Punch Card Logic: 1 punch per 200 points, 6 punches = reward
  const POINTS_PER_PUNCH = 200
  const totalPunches = 6
  const currentPunches = Math.floor((user?.points_balance || 0) / POINTS_PER_PUNCH) % totalPunches
  const moreToGo = totalPunches - currentPunches

  const handleSave = async () => {
    setLoading(true)
    setSaveStatus('')
    try {
