                        (red) => red.reward_id === r.id || (red.reward && red.reward.id === r.id)
                      ).length
                      const isReached = r.limit_per_user > 0 && redemptionCount >= r.limit_per_user
                      const isSoldOut = r.total_limit > 0 && r.redemptions_count >= r.total_limit

                      return (
